import type Anthropic from '@anthropic-ai/sdk'
import {
  getLanguageName,
  isSupportedLanguageCode,
  type SupportedLanguageCode,
} from '@flicktionary/core/constants/supported-languages'
import {
  cachedSystem,
  getAnthropicClient,
  MODEL_HAIKU,
  MODEL_TRANSLATE,
  reasoningParams,
  TOOL_CHOICE_AUTO,
} from '../anthropic-client'
import { logAnthropicCacheUsage } from '../log-cache-usage'

// The quick lane of "Translate & add" (MODEL_TRANSLATE): turns whatever the learner typed (a
// native-language phrase, an English word, or a target-language word) into
// 1-3 target-language candidates to pick from. Only a picker — the card itself
// is generated by the basic-data pass when a candidate is added, so a weak
// candidate costs a skipped suggestion, not a bad card.

const TOOL_NAME = 'submit_candidates'
const MAX_INPUT_CHARS = 500
const MAX_CONTEXT_CHARS = 2000
const MAX_OPTIONS = 3

export type CaptureCandidate = {
  headword: string
  note: string
  example: string
}

export type TranslateForCaptureResult = {
  inputLanguage: SupportedLanguageCode | null
  candidates: CaptureCandidate[]
}

const buildTool = (): Anthropic.Tool => ({
  name: TOOL_NAME,
  description: 'Submit the target-language candidates for the learner to pick from.',
  strict: true,
  input_schema: {
    type: 'object',
    additionalProperties: false,
    properties: {
      input_language: {
        type: 'string',
        description: "ISO 639-1 code of the language the learner typed in, or 'und' if unclear.",
      },
      candidates: {
        type: 'array',
        items: {
          type: 'object',
          additionalProperties: false,
          properties: {
            headword: {
              type: 'string',
              description:
                'The target-language term in dictionary citation form, following the language conventions (no stress marks; e.g. Russian verbs: the aspect that fits best; German nouns: bare noun without article).',
            },
            note: {
              type: 'string',
              description:
                'One short line: the meaning plus what distinguishes this candidate (register, aspect, nuance). No headword repetition.',
            },
            example: {
              type: 'string',
              description: 'One short, natural target-language sentence using the term in this meaning.',
            },
          },
          required: ['headword', 'note', 'example'],
        },
      },
    },
    required: ['input_language', 'candidates'],
  },
})

export const translateForCapturePass = async (args: {
  text: string
  // Where the learner met the term, pasted as-is.
  context?: string | null
  targetLanguage: string
  nativeLanguage: string
  // Translations-off learners get notes in the target language (immersion).
  hideTranslationFields: boolean
}): Promise<TranslateForCaptureResult> => {
  const target = getLanguageName(args.targetLanguage)
  const noteLanguage = getLanguageName(args.hideTranslationFields ? args.targetLanguage : args.nativeLanguage)
  const system = `You help a language learner capture vocabulary in ${target}. The learner's native language is ${getLanguageName(args.nativeLanguage)}.

The learner types a word, expression, or short phrase, usually in their native language or English, and wants to know how to say it in ${target}.

Rules:
- If the input is NOT in ${target}: return 1 to ${MAX_OPTIONS} candidates, most common and natural first. Give more than one only when the alternatives genuinely differ (register, aspect, regional use, nuance); never pad with near-duplicates.
- If the input IS already in ${target}: return exactly one candidate for it, normalized to citation form, with its meaning in the note.
- If the input is a ${target} sentence: return candidates for its one or two most useful chunks, using the sentence as their example.
- Prefer the chunk a native speaker would actually say over a literal word-for-word rendering. For a whole clause or idiom ("I'm exhausted", "je suis crevé"), give the natural everyday equivalent a native speaker would say, as a phrase, rather than a dictionary word for the literal meaning.
- Write every note in ${noteLanguage}, one short line.
- The learner may add the context they met the term in. It is pasted as-is: it can be a fragment, contain mistakes, or be much longer than one sentence. When it is given:
  - Pick the candidates, and their order, for the sense the context needs.
  - Base each example on the context so the card reminds the learner of where they met the term. If the context is in ${target} and uses the term, keep its wording and situation, but cut it down to one short sentence around the term, complete a fragment, and fix any mistakes. Otherwise, write a short ${target} sentence expressing the context's situation with the term.
  - The example must still be a short, natural, correct ${target} sentence using the candidate.
- Call ${TOOL_NAME} once.`

  const text = args.text.trim().slice(0, MAX_INPUT_CHARS)
  const context = args.context?.trim().slice(0, MAX_CONTEXT_CHARS)
  const userContent = context ? `${text}\n\n<context>\n${context}\n</context>` : text

  const response = await getAnthropicClient().messages.create({
    model: MODEL_TRANSLATE,
    // Every model runs at its lowest reasoning setting (see reasoningParams).
    ...reasoningParams(MODEL_TRANSLATE, 'low'),
    max_tokens: 1000,
    system: cachedSystem(system),
    tools: [buildTool()],
    // Opus 5.5 rejects a forced tool_choice; the prompt names the tool, which
    // is how the other Opus passes get their tool call.
    tool_choice: MODEL_TRANSLATE === MODEL_HAIKU ? { type: 'tool', name: TOOL_NAME } : TOOL_CHOICE_AUTO,
    messages: [{ role: 'user', content: userContent }],
  })
  logAnthropicCacheUsage('translate-for-capture', response)

  const toolUse = response.content.find((block) => block.type === 'tool_use')
  if (!toolUse || toolUse.type !== 'tool_use') {
    throw new Error('Translate-for-capture did not produce a tool_use block')
  }
  return parseTranslateForCaptureInput(toolUse.input)
}

export const parseTranslateForCaptureInput = (raw: unknown): TranslateForCaptureResult => {
  const input = (raw ?? {}) as { input_language?: unknown; candidates?: unknown }
  const languageCandidate = typeof input.input_language === 'string' ? input.input_language.trim().toLowerCase() : ''
  const candidates = (Array.isArray(input.candidates) ? input.candidates : [])
    .map((c): CaptureCandidate | null => {
      const item = (c ?? {}) as Record<string, unknown>
      const headword = typeof item.headword === 'string' ? item.headword.trim() : ''
      if (!headword) return null
      return {
        headword,
        note: typeof item.note === 'string' ? item.note.trim() : '',
        example: typeof item.example === 'string' ? item.example.trim() : '',
      }
    })
    .filter((c): c is CaptureCandidate => c !== null)
    .slice(0, MAX_OPTIONS)
  return {
    inputLanguage: isSupportedLanguageCode(languageCandidate) ? languageCandidate : null,
    candidates,
  }
}
